"function model
dt = 0.02;
Ydata = X(2:end,:);
Phi = [X(1:end-1,:), u(1:end-1)];
Theta = Phi\Ydata; %#ok<NOBRACK>
Ad = Theta(1:4,:);
lam = eig(Ad);
s = log(lam)/dt;
% select conjugate pair with largest |s|
[~,idx] = sort(abs(s),'descend');
sp = s(idx(1));
omega_sp_id = abs(sp);
zeta_sp_id = -real(sp)/omega_sp_id;
res = struct('omega_sp_id',omega_sp_id,'zeta_sp_id',zeta_sp_id);
fid = fopen('result.json','w');
fwrite(fid,jsonencode(res),'char');
fclose(fid);
end"

